changeSet.sql:
create or alter procedure [graph].[GetHop] @assets dbo.AssetBrowserImpactTable readonly, @hopSalt varchar(25), @direction char(1), -- (F)orward, (B)ackward, (I)mpact, or '' (Initial)? @predicateUid uniqueidentifier as begin set nocount on;
drop table if exists #assetIds create table #assetIds ([Uid] uniqueidentifier, ID bigint, Class int, [Key] varchar(50)) create index ix_TempAssetIds on #assetIds (ID asc)
drop table if exists #links; create table #links ( [Uid] uniqueidentifier, Direction char(1), ProvidedKey varchar(50), [Key] varchar(50), ID bigint, [AssetUid] uniqueidentifier, [Path] nvarchar(2500), [Segment] xml, PredicateId int, PredicateUid uniqueidentifier, [Predicate] nvarchar(250), PredicateType int);
drop table if exists #nodes create table #nodes ( [Level] int, AssetUid uniqueidentifier, AssetID bigint, [Key] varchar(50), ParentID bigint null, ParentKey varchar(50), Back varchar(25), Fore varchar(25), Icon varchar(50), AssetTypeID int, AssetTypeUid uniqueidentifier, Class int, DisplayValue nvarchar(500), Reveal int, RelationCounts varchar(max), UseAsTransformation bit null, IsLeaf bit, IsSubjectInTransformation bit null);
insert into #assetIds select distinct A.Uid, A.ID, T.[Class], O.[Key] from Asset A inner join @assets O on O.Uid = A.Uid inner join AssetType T on T.ID = A.AssetTypeID;
-- Backward-facing hop if @direction = 'B' begin insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID as ToID, S.Uid as ToUid, S.[Path] as ToPath, S.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in (12,13) and P.[Uid] = E.PredicateUid and T.ID = A.ID; end else if @direction = 'F' -- Forward-facing hop begin insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Inverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in (12,13) and P.[Uid] = E.PredicateUid and S.ID = A.ID; end; else if @direction = 'I' -- Impact hop begin insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID as ToID, S.Uid as ToUid, S.[Path] as ToPath, S.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType not in (3,4,12,13) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and T.ID = A.ID;
insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Inverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType not in (3,4,12,13) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and S.ID = A.ID; end; else begin insert into #links (Direction, [Key], ID, AssetUid, [Path], [Segment]) select @direction, A.[Key],
N.ID as ToID, N.Uid as ToUid, N.[Path] as ToPath, N.Segments as ToSegment
from graph.AssetNode N, #assetIds A where N.ID = A.ID; end;
with cte as ( select Segment.query(' <path> { let $segments := (/path/segment) for $x in $segments return <segment> <level>{data($x/@level)}</level> <assetTypeId>{data($x/@assetTypeId)}</assetTypeId> <assetId>{data($x/@assetId)}</assetId> <parentAssetId>{data(/path/segment[. << $x][last()]/@assetId)}</parentAssetId> <value>{data($x)}</value> <leaf>{$x is $segments[last()]}</leaf> </segment> } </path> ') as Segment, [Key], AssetUid from #links )
insert into #nodes ([Level], AssetUid, AssetID, [Key], ParentID, ParentKey, Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, RelationCounts, UseAsTransformation, IsLeaf) select distinct doc.c.value('(level/text())[1]', 'int') as [Level] ,A.Uid as AssetUid ,doc.c.value('(assetId/text())[1]', 'bigint') as AssetID ,case when T.[Key] is not null and A.Uid = T.AssetUid then T.[Key] else utility.GetHash(@hopSalt + '|' + cast(A.ID as varchar(50))) end as [Key] ,doc.c.value('(parentAssetId/text())[1]', 'bigint') as ParentID ,utility.GetHash(@hopSalt + '|' + doc.c.value('(parentAssetId/text())[1]', 'varchar(50)')) as [ParentKey] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,doc.c.value('(assetTypeId/text())[1]', 'int') as AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,doc.c.value('(value/text())[1]', 'nvarchar(250)') as DisplayValue ,0 as Reveal ,'[]' as RelationCounts ,0 as UseAsTransformation ,case when doc.c.value('(leaf/text())[1]', 'nvarchar(1)') = 't' then cast(1 as bit) else cast(0 as bit) end as IsLeaf from cte T cross apply T.Segment.nodes('/path/segment') doc(c) inner join AssetWithType A on A.ID = doc.c.value('(assetId/text())[1]', 'bigint');
-- Get type-based parent for single-level asset hierarchies above. if @direction = 'B' or @direction = 'F' begin insert into #nodes ([Level], AssetUid, AssetID, [Key], ParentID, ParentKey, Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, RelationCounts, UseAsTransformation) select 1 as [Level], CAST(0x0 AS UNIQUEIDENTIFIER) as AssetUid, 0 as AssetID, utility.GetHash(@hopSalt + '|' + cast(AssetTypeUid as varchar(50))) as [Key], null as ParentID, null as ParentKey, n.Back, n.Fore, n.Icon, n.AssetTypeID, n.AssetTypeUid, n.Class, t.Name as DisplayValue, n.Reveal, n.RelationCounts, t.UseAsTransformation from #nodes n inner join #links l on l.[Key] = n.[Key] and n.[ParentKey] is null inner join AssetType t on t.ID = n.AssetTypeID;
update t set t.ParentID = t.AssetTypeID, t.ParentKey = utility.GetHash(@hopSalt + '|' + cast(t.AssetTypeUid as varchar(50))), t.[Level] = 2 from #nodes t inner join #links l on l.[Key] = t.[Key] and t.[ParentKey] is null; end else begin insert into #nodes ([Level], AssetUid, AssetID, [Key], ParentID, ParentKey, Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, RelationCounts, UseAsTransformation) select 1 as [Level], CAST(0x0 AS UNIQUEIDENTIFIER) as AssetUid, 0 as AssetID, utility.GetHash(@hopSalt + '|' + cast(AssetTypeUid as varchar(50))) as [Key], null as ParentID, null as ParentKey, n.Back, n.Fore, n.Icon, n.AssetTypeID, n.AssetTypeUid, n.Class, t.Name as DisplayValue, n.Reveal, n.RelationCounts, t.UseAsTransformation from #nodes n inner join AssetType t on t.ID = n.AssetTypeID and n.[ParentKey] is null;
update t set t.ParentID = t.AssetTypeID, t.ParentKey = utility.GetHash(@hopSalt + '|' + cast(t.AssetTypeUid as varchar(50))), t.[Level] = 2 from #nodes t inner join #nodes l on l.assetTypeId = t.assetTypeId and t.[ParentKey] is null and t.assetID > 0; end
-- Determine UseAsTransformation update T set T.UseAsTransformation = S.UseAsTransformation, T.IsSubjectInTransformation = CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END from #nodes T inner join AssetType S on S.ID = T.AssetTypeID cross apply ( select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = S.Object and IT.SubjectID = S.ObjectID ) ATO(Cnt); -- Calculate reveal. if @direction = 'B' begin update R set R.Reveal = case when S.[Count] > 0 then 2 else 0 end from #nodes R cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (12,13) and T.ID = R.AssetID ) S; end
if @direction = 'F' begin update R set R.Reveal = case when S.[Count] > 0 then 1 else 0 end from #nodes R cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType in (12,13) and S.ID = R.AssetID ) S; end
-- Get badges update R set R.RelationCounts = coalesce( ( select [Predicate], ID as PredicateID, Uid as PredicateUid, Direction, count(1) as [Count] from ( select P.Name as [Predicate], P.ID, P.Uid, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and S.ID = R.AssetID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13) union select P.Inverse as [Predicate], P.ID, P.Uid, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and T.ID = R.AssetID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13) ) O group by [Predicate], ID, Uid, Direction for json path ), '[]' ) from #nodes R;
-- Return to caller select assetUid, assetId, [key], parentId, parentKey, back, fore, icon, assetTypeId, assetTypeUid, class, displayValue, reveal, relationCounts, useAsTransformation, isSubjectInTransformation, isLeaf from #nodes order by [Level];
select [uid] ,case Direction when 'F' then ProvidedKey else [Key] end as subjectKey ,case Direction when 'F' then [Key] else ProvidedKey end as objectKey ,predicateId ,predicateUid ,[predicate] ,predicateType from #links where [Key] is not null and ProvidedKey is not null;
end

changeSet.rollback:
CREATE OR ALTER procedure [graph].[GetLineageByAsset] @assets dbo.UidTable readonly, @isReveal bit = 0, @StartHop int = 0, @direction int = 3, @hops int = 5 as begin set nocount on;
if @hops > 25 begin set @hops = 25 end if @hops <= 0 begin set @hops = 3 end if @direction not between 1 and 3 begin set @direction = 3 end
drop table if exists #assetIds drop table if exists #clean drop table if exists #hierarchies drop table if exists #mappedAssetIds drop table if exists #rawHierarchies drop table if exists #singles drop table if exists #tbl
create table #assetIds (ID bigint, Class int) create index ix_TempAssetIds on #assetIds (ID asc)
create table #clean ([Hop] int, ID bigint, [Path] nvarchar(2500), Segment xml, Reveal int)
create table #hierarchies ([Hop] int, ID bigint, [Key] varchar(50), Back varchar(25), Fore varchar(25), Icon varchar(50), HierarchyLevel int, AssetTypeID int,AssetTypeUid uniqueidentifier, AssetID bigint, AssetUid uniqueidentifier, DisplayValue nvarchar(500), Class int, AssetTypeName nvarchar(250), Reveal int, RelationCounts varchar(max), XmlPosition int, ParentKey varchar(50), ParentID bigint null, IsDupe bit null, UseAsTransformation bit null, IsSubjectInTransformation bit null) create index ix_TempHierarchies on #hierarchies ([Hop] asc, HierarchyLevel asc)
create table #mappedAssetIds (RowOrder int identity, ID bigint, Class int, AddToAssetTemp bit, BusinessAssetID bigint) create index ix_TempMappedAssetIds on #mappedAssetIds (ID asc)
create table #rawHierarchies ([Hop] int, ID bigint, HierarchyLevel int, AssetTypeID int, AssetID bigint, ParentID bigint, Reveal int); create index IX_TempRawHierarchies on #rawHierarchies (AssetTypeID asc, AssetID asc); create clustered index CIX_TempRawHierarchies on #rawHierarchies (Hop asc, ID asc, HierarchyLevel asc);
create table #singles (Hop int, ID bigint)
create table #tbl ( [Hop] int, Uid uniqueidentifier, FromReveal bit, FromHop int, FromID bigint, subjectUid uniqueidentifier, FromPath nvarchar(2500), FromSegment xml, ToReveal bit, ToHop int, ToID bigint, objectUid uniqueidentifier, ToPath nvarchar(2500), ToSegment xml, predicateId int, predicateUid uniqueidentifier, [predicate] nvarchar(250), predicateType int, traverse bit) create index ix_TempTbl on #tbl ([Hop] desc, ToID asc)
declare @maxHops int = @hops + @StartHop
insert into #assetIds select distinct A.ID, T.[Class] from Asset A inner join @assets O on O.Uid = A.Uid inner join AssetType T on T.ID = A.AssetTypeID
if not exists(select 1 from #assetIds) begin insert into #assetIds values(0, 0) end;
-- Get any descendant assets that may contain lineage data, but only if this is not a reveal call. Reveals are getting data only for a specific set of assets, descendants are already taken into account. if @isReveal = 0 begin with descendants as ( select S.ID as FromID, T.ID as ToID, T.AssetTypeID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = A.ID union all select S.ID as FromID, T.ID as ToID, T.AssetTypeID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, descendants p where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = p.ToID ) insert into #assetIds select distinct D.ToID, T.Class from descendants D inner join AssetType T on T.ID = D.AssetTypeID; end;
-- Get any technical assets that are associated via the Business-To-Technical mapping predicate. with tech_descendants as ( select T.ID, T.Class, 1 as AddToAssetTemp, A.ID as BusinessAssetID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType = 13 -- Business To Technical predicate type and S.ID = A.ID and A.Class <> 8 union all select T.ID, T.Class, p.AddToAssetTemp, p.BusinessAssetID from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, tech_descendants p where MATCH(S-(E)->T) and E.PredicateType in (3, 4) and S.ID = p.ID ) insert into #mappedAssetIds select ID, Class, AddToAssetTemp, BusinessAssetID from tech_descendants;
-- Now remove the assets that trigger the inference. We will add them back later. delete T from #assetIds T inner join #mappedAssetIds S on S.BusinessAssetID = T.ID
-- If not business asset that triggered an inference check, add dummy to at least let loop execute. if not exists(select top 1 * from #mappedAssetIds) begin insert into #mappedAssetIds values (0,0,0,0) --add dummy record if no inference records to start end
while exists (select top 1 * from #mappedAssetIds order by RowOrder) begin declare @assetId bigint, @class int, @AddToAssetTemp bit select top 1 @assetId = ID, @class = [Class], @AddToAssetTemp = AddToAssetTemp from #mappedAssetIds order by RowOrder
if @AddToAssetTemp = 1 begin insert into #assetIds values (@assetId, @class) end
delete #mappedAssetIds where ID = @assetId
-- Backward-facing crawl - starting jump if @direction = 2 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, predicateType, traverse) select @StartHop as [Hop], E.Uid,
0 as FromReveal, iif(E.PredicateType = 13, 0, @StartHop-1) as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment,
0 as ToReveal, @StartHop as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType,
1 as traverse
from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType in(12,13) and T.ID = A.ID; end;
-- Forward-facing crawl - starting jump if @direction = 1 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, predicateType, traverse) select @StartHop as [Hop], E.Uid,
0 as FromReveal, iif(E.PredicateType = 13, 0, @StartHop) as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment,
0 as ToReveal, @StartHop+1 as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType,
1 as traverse
from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #assetIds A where MATCH(S-(E)->T) and E.PredicateType = 12 and S.ID = A.ID; end;
declare @current int = @StartHop+1; while @current < @maxHops begin -- Backward-facing crawl if @direction = 2 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, predicateType, traverse) select -@current as [Hop], E.Uid,
0 as FromReveal, iif(E.PredicateType = 13, 0, -@current-1) as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment,
0 as ToReveal, -@current as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, iif(E.PredicateType = 13, 0, 1) as traverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #tbl b where MATCH(S-(E)->T) and E.PredicateType in (12, 13) and T.ID = b.FromID and b.[Hop] = -@current+1 and b.traverse = 1 and E.Uid not in (select Uid from #tbl) end;
-- Forward-facing crawl if @direction = 1 or @direction = 3 begin insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, predicateType, traverse) select @current as [Hop], E.Uid,
0 as FromReveal, iif(E.PredicateType = 13, 0, @current) as FromHop, S.ID as FromID, S.Uid as FromUid, S.[Path] as FromPath, S.Segments as FromSegment,
0 as ToReveal, @current+1 as ToHop, T.ID as ToID, T.Uid as ToUid, T.[Path] as ToPath, T.Segments as ToSegment,
E.PredicateID, E.PredicateUid, E.PredicateType, iif(E.PredicateType = 13, 0, 1) as traverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #tbl f where MATCH(S-(E)->T) and E.PredicateType in (12,13) and S.ID = f.ToID and f.[Hop] = @current-1 and f.traverse = 1 and E.Uid not in (select Uid from #tbl) end;
set @current = @current +1 end
-- Calculate REVEALS if @direction = 2 or @direction = 3 -- Backward-facing REVEAL begin update R set R.FromReveal = case when S.[Count] > 0 then 1 else 0 end from #tbl R cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType = 12 and T.ID = R.FromID and R.[Hop] = case @isReveal when 1 then @StartHop else -@current+1 end and E.Uid not in (select Uid from #tbl) ) S end;
if @direction = 1 or @direction = 3 -- Forward-facing REVEAL begin update R set R.ToReveal = case when S.[Count] > 0 then 1 else 0 end from #tbl R cross apply ( select count(1) as [Count] from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T where MATCH(S-(E)->T) and E.PredicateType = 12 and S.ID = R.FromID and R.[Hop] = case @isReveal when 1 then @StartHop else @current-1 end and E.Uid not in (select Uid from #tbl) ) S end;
-- Populate the predicate name. update T set T.[predicate] = S.Name from #tbl T inner join [Predicate] S on S.Uid = T.predicateUid;
delete #mappedAssetIds where ID in (select FromID from #tbl) delete #mappedAssetIds where ID in (select ToID from #tbl) end
-- Now load any inferred links from the assetIDs table listed above. --1. Check Subject side first insert into #tbl ([Hop], Uid, FromHop, FromID, subjectUid, FromPath, FromSegment, ToHop, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, [predicate], predicateType, traverse) select C.[Hop], E.Uid,
case E.PredicateType when 13 then 0 else C.FromHop-1 end, S.ID, S.Uid, S.[Path], S.Segments,
C.FromHop, C.FromID, C.subjectUid, C.FromPath, C.FromSegment,
E.PredicateID, E.PredicateUid, P.Name as [Predicate], E.PredicateType, 0 as traverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #tbl C, [Predicate] P where MATCH(S-(E)->T) and E.PredicateType = 13 and T.ID = C.FromID and P.ID = E.PredicateID;
-- Get cleaned up version of unique nodes based on Hop and AssetUid. insert into #clean select FromHop, FromID, FromPath, FromSegment, case when FromReveal = 1 then 2 else 0 end from ( select Row_number() over(partition by FromHop,FromID order by FromHop,FromID) as RowNum, FromHop, FromID, FromPath, FromSegment, FromReveal from #tbl ) O where RowNum = 1
insert into #clean select ToHop, ToID, ToPath, ToSegment, case when ToReveal = 1 then 2 else 0 end from ( select Row_number() over(partition by ToHop,ToID order by ToHop,ToID) as RowNum, ToHop, ToID, ToPath, ToSegment, ToReveal from #tbl N left join #clean E on E.Hop = N.ToHop and E.ID = N.ToID where E.ID is null ) O where RowNum = 1;
if not exists (select 1 from #clean) begin declare @incomingAssetCount int = 0 select @incomingAssetCount = count(1) from @assets
if @incomingAssetCount = 1 begin -- Insert the single asset into the table. insert into #clean select 0, A.ID, N.[Path], N.Segments, 0 from #assetIds A inner join graph.AssetNode N on N.ID = A.ID end end
insert into #rawHierarchies select distinct T.[Hop], T.ID, doc.c.value('@level', 'int') as [HierarchyLevel], doc.c.value('@assetTypeId', 'int') as [assetTypeId], doc.c.value('@assetId', 'bigint') as [assetId], null, T.Reveal from #clean T cross apply T.Segment.nodes('/path/segment') doc(c);
update T set T.ParentID = S.AssetID from #rawHierarchies T inner join #rawHierarchies S on S.Hop = T.Hop and S.ID = T.ID and S.HierarchyLevel = T.HierarchyLevel-1;
insert into #hierarchies select distinct T.[Hop],
T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + cast(T.AssetID as varchar(50))) as [Key], coalesce(S.[IconBackColor], '#000000'), coalesce(S.[IconForeColor], '#FFFFFF'), N.Icon, T.[HierarchyLevel], T.AssetTypeID, [AT].uid as AssetTypeUid, T.AssetID, A.Uid, d.DisplayValue, [AT].Class, [AT].Name as AssetTypeName, T.Reveal, '[]', null,--T.XmlPosition, null, T.ParentID, 0,--1 as IsDupe, [AT].UseAsTransformation, CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END AS IsSubjectInTransformation from #rawHierarchies T inner join AssetDisplayValue d on d.AssetID = T.AssetID inner join AssetType [AT] on [AT].ID = T.AssetTypeID left join AssetTypeStyle S on S.ID = [AT].ID cross apply dbo.GetAssetTypeIconById(T.AssetTypeID) N inner join Asset A on A.ID = d.AssetID cross apply (select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = AT.Object and IT.SubjectID = AT.ObjectID)ATO(Cnt);
-- Determine relationships breakdown by predicate. declare @relItems table (Hop int, AssetID bigint, [Predicate] nvarchar(250), PredicateId int, PredicateUid uniqueidentifier, Direction int, AssetUid uniqueidentifier) insert into @relItems select H.Hop, H.ID, P.Inverse, P.ID, P.Uid, 1, T.Uid from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #clean H, [Predicate] P where MATCH(S-(E)->T) and S.ID = H.ID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13) union select H.Hop, H.ID, P.Inverse, P.ID, P.Uid, 2, S.Uid from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #clean H, [Predicate] P where MATCH(S-(E)->T) and T.ID = H.ID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13);
update H set H.RelationCounts = ( select O.[Predicate], O.Direction, O.PredicateId, O.PredicateUid, count(1) as [Count] from @relItems O where O.Hop = H.Hop and O.AssetID = H.AssetID group by O.[Predicate], O.PredicateId, O.PredicateUid, O.Direction for json path ) from #hierarchies H
--Add Type as parent to those nodes that have a single-level hierarchy. insert into #singles select H.Hop, H.ID from #hierarchies H left join #hierarchies P on P.ParentID = H.ID where P.ID is null group by H.Hop, H.ID having count(1) = 1;
update T set T.HierarchyLevel = 2, T.XmlPosition = 2 from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
insert into #hierarchies select T.Hop, T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + cast(A.Uid as varchar(50))), T.Back, T.Fore, T.Icon, 1 as HierarchyLevel, T.AssetTypeID, [A].uid as AssetTypeUid, A.ID as AssetID, CAST(0x0 AS UNIQUEIDENTIFIER) as AssetUid, A.Name as DisplayValue, A.Class, A.Name as AssetTypeName, 0 as Reveal, '[]' as RelationCounts, 1 as XmlPosition, null as ParentKey, null as ParentID, 0 as IsDupe, A.UseAsTransformation, CASE WHEN ATO.Cnt = 0 THEN 0 ELSE 1 END AS IsSubjectInTransformation from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID inner join AssetType A on A.ID = T.AssetTypeID cross apply (select count(*) from IntersectType IT left join AssetType ATO on ATO.Object = IT.Object and ATO.ObjectID = IT.ObjectID and ATO.UseAsTransformation = 1 where IT.Subject = A.Object and IT.SubjectID = A.ObjectID)ATO(Cnt);
update T set T.ID = T.AssetTypeID from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
-- Resolve the parent key. update C set C.ParentKey = P.[Key] from #hierarchies C left join #hierarchies P on P.Hop = C.Hop and P.ID = C.ID and P.XmlPosition = C.XmlPosition-1;
update C set C.ParentKey = P.[Key] from #hierarchies C left join #hierarchies P on P.Hop = C.Hop and P.ID = C.ID and P.AssetID = C.ParentID where C.ParentID is not null;
-- Cleanup update #hierarchies set Reveal = 0 where Reveal is null;
-- Now return the data sets to caller.
--select * from #clean order by Hop;
delete T from #hierarchies T inner join #hierarchies S on S.[Key] = T.[Key] and T.Reveal = 0 and S.Reveal <> 0;
select distinct Hop, [Key], ParentKey, Back, Fore, Icon, HierarchyLevel, AssetTypeID, AssetTypeUid, AssetID, AssetUid, DisplayValue, Class, AssetTypeName, Reveal, RelationCounts, UseAsTransformation, IsSubjectInTransformation from #hierarchies order by Hop, HierarchyLevel, DisplayValue;
select distinct [Hop], Uid, subjectUid, utility.GetHash(cast([FromHop] as varchar) + '|' + cast(FromID as varchar(50))) as [subjectKey], FromID as subjectId, objectUid, utility.GetHash(cast([ToHop] as varchar) + '|' + cast(ToID as varchar(50))) as [objectKey], ToID as objectId, predicateId, predicateUid, [predicate], predicateType from #tbl order by Hop; end

CREATE OR ALTER procedure [graph].[GetImpactRelationshipsByAssets] @assets dbo.AssetBrowserImpactTable readonly, @predicateUid uniqueidentifier, @StartHop int = 0 as begin set nocount on;
drop table if exists #assetIds drop table if exists #clean drop table if exists #hierarchies drop table if exists #rawHierarchies drop table if exists #tbl
create table #assetIds (ID bigint, [Key] varchar(100), Class int) create index ix_TempAssetIds on #assetIds (ID asc)
create table #clean ([Hop] int, [Key] varchar(100), ID bigint, [Path] nvarchar(2500), Segment xml, Reveal int)
create table #hierarchies ([Hop] float, ID bigint, [Key] varchar(50), Back varchar(25), Fore varchar(25), Icon varchar(50), HierarchyLevel int, AssetTypeID int, AssetID bigint, AssetUid uniqueidentifier, DisplayValue nvarchar(500), Class int, AssetTypeName nvarchar(250), Reveal int, RelationCounts varchar(max), XmlPosition int, ParentKey varchar(50), ParentID bigint null, IsDupe bit null) create index ix_TempHierarchies on #hierarchies ([Hop] asc, HierarchyLevel asc)
create table #rawHierarchies ([Hop] int, ID bigint, HierarchyLevel int, AssetTypeID int, AssetID bigint, ParentID bigint, Reveal int); create index IX_TempRawHierarchies on #rawHierarchies (AssetTypeID asc, AssetID asc); create clustered index CIX_TempRawHierarchies on #rawHierarchies (Hop asc, ID asc, HierarchyLevel asc);
create table #tbl ( [Hop] int, Uid uniqueidentifier, FromReveal bit, FromHop int, FromKey varchar(100), FromID bigint, subjectUid uniqueidentifier, FromPath nvarchar(2500), FromSegment xml, ToReveal bit, ToHop int, ToKey varchar(100), ToID bigint, objectUid uniqueidentifier, ToPath nvarchar(2500), ToSegment xml, predicateId int, predicateUid uniqueidentifier, [predicate] nvarchar(250), predicateType int) create index ix_TempTbl on #tbl ([Hop] desc, ToID asc)
declare @maxHops int = 1 + @StartHop
insert into #assetIds select distinct A.ID, O.[Key], T.[Class] from Asset A inner join @assets O on O.Uid = A.Uid inner join AssetType T on T.ID = A.AssetTypeID
if not exists(select 1 from #assetIds) begin insert into #assetIds values(0, null, 0) end;
-- Upstream impacts insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromKey, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToKey, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, [predicate], predicateType) select @StartHop as [Hop], E.Uid,
-- FROM 0, @StartHop, A.[Key], T.ID, T.Uid, T.[Path], T.Segments,
-- TO 0, 0,--@StartHop-1,---1 as FromHop, null, S.ID, S.Uid, S.[Path], S.Segments,
P.ID, E.PredicateUid, P.[Inverse], E.PredicateType
from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType not in (3,4,12,13) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and T.ID = A.ID;
-- Downstream impacts insert into #tbl ([Hop], Uid, FromReveal, FromHop, FromKey, FromID, subjectUid, FromPath, FromSegment, ToReveal, ToHop, ToKey, ToID, objectUid, ToPath, ToSegment, predicateId, predicateUid, [predicate], predicateType) select @StartHop as [Hop], E.Uid,
-- FROM 0, @StartHop, A.[Key], S.ID, S.Uid, S.[Path], S.Segments,
-- TO 0, 0,--@StartHop-1,--+1 as ToHop, null, T.ID, T.Uid, T.[Path], T.Segments,
P.ID, E.PredicateUid, P.Name, E.PredicateType from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateType not in (3,4,12,13) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and S.ID = A.ID;
-- Get cleaned up version of unique nodes based on Hop and AssetUid. insert into #clean ([Hop], [Key], ID, [Path], Segment, Reveal) select FromHop, FromKey, FromID, FromPath, FromSegment, case when FromReveal = 1 then 2 else 0 end from ( select Row_number() over(partition by FromHop, FromID order by FromHop, FromID) as RowNum, FromHop, FromKey, FromID, FromPath, FromSegment, FromReveal from #tbl where FromPath is not null ) O where RowNum = 1
insert into #clean ([Hop], [Key], ID, [Path], Segment, Reveal) select ToHop, ToKey, ToID, ToPath, ToSegment, case when ToReveal = 1 then 2 else 0 end from ( select Row_number() over(partition by ToHop, ToID order by ToHop, ToID) as RowNum, ToHop, ToKey, ToID, ToPath, ToSegment, ToReveal from #tbl N left join #clean E on E.Hop = N.ToHop and E.ID = N.ToID where E.ID is null and ToPath is not null ) O where RowNum = 1
-- We only want to create assets that do not have the key column populated, as those Key-populated assets came into the proc, and already exist. insert into #rawHierarchies select distinct T.[Hop], T.ID, doc.c.value('@level', 'int') as [HierarchyLevel], doc.c.value('@assetTypeId', 'int') as [assetTypeId], doc.c.value('@assetId', 'bigint') as [assetId], null, T.Reveal from #clean T cross apply T.Segment.nodes('/path/segment') doc(c) where T.[Key] is null;
update T set T.ParentID = S.AssetID from #rawHierarchies T inner join #rawHierarchies S on S.Hop = T.Hop and S.ID = T.ID and S.HierarchyLevel = T.HierarchyLevel-1
insert into #hierarchies select T.[Hop],
T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + cast(T.AssetID as varchar(50))) as [Key], coalesce(S.[IconBackColor], '#000000'), coalesce(S.[IconForeColor], '#FFFFFF'), N.Icon, T.[HierarchyLevel], T.AssetTypeID, T.AssetID, A.Uid, d.DisplayValue, [AT].Class, [AT].Name as AssetTypeName, T.Reveal, '[]', null, null, T.ParentID, 0 as IsDupe from #rawHierarchies T inner join AssetDisplayValue d on d.AssetID = T.AssetID inner join AssetType [AT] on [AT].ID = T.AssetTypeID left join AssetTypeStyle S on S.ID = [AT].ID cross apply dbo.GetAssetTypeIconById(T.AssetTypeID) N inner join Asset A on A.ID = d.AssetID;
--Add Type as parent to those nodes that have a single-level hierarchy. drop table if exists #singles create table #singles (Hop int, ID bigint) insert into #singles select Hop, ID from #hierarchies group by Hop, ID having count(1) = 1;
update T set T.HierarchyLevel = 2, T.XmlPosition = 2 from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
insert into #hierarchies select T.Hop, T.ID, utility.GetHash(cast(T.[Hop] as varchar) + '|' + cast(A.Uid as varchar(50))), T.Back, T.Fore, T.Icon, 1 as HierarchyLevel, T.AssetTypeID, A.ID as AssetID, CAST(0x0 AS UNIQUEIDENTIFIER) as AssetUid, --A.Uid as AssetUid, A.Name as DisplayValue, A.Class, A.Name as AssetTypeName, 0 as Reveal, '[]' as RelationCounts, 1 as XmlPosition, null as ParentKey, null as ParentID, 0 as IsDupe from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID inner join AssetType A on A.ID = T.AssetTypeID;
update T set T.ID = T.AssetTypeID from #hierarchies T inner join #singles S on S.Hop = T.Hop and S.ID = T.ID;
-- Resolve the parent key. update C set C.ParentKey = P.[Key] from #hierarchies C left join #hierarchies P on P.Hop = C.Hop and P.ID = C.ID and P.XmlPosition = C.XmlPosition-1;
update C set C.ParentKey = P.[Key] from #hierarchies C left join #hierarchies P on P.Hop = C.Hop and P.ID = C.ID and P.AssetID = C.ParentID where C.ParentID is not null;
-- Cleanup update #hierarchies set Reveal = 0 where Reveal is null;
-- Determine relationships breakdown by predicate. declare @relItems table (Hop int, AssetID bigint, [Predicate] nvarchar(250), PredicateId int, PredicateUid uniqueidentifier, Direction int, AssetUid uniqueidentifier) insert into @relItems select H.Hop, H.ID, P.Name, P.ID, P.Uid, 1, T.Uid from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #clean H, [Predicate] P where MATCH(S-(E)->T) and S.ID = H.ID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13) union select H.Hop, H.ID, P.Inverse, P.ID, P.Uid, 2, S.Uid from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, #clean H, [Predicate] P where MATCH(S-(E)->T) and T.ID = H.ID and P.ID = E.PredicateID and E.PredicateType not in (3,4,12,13);
update H set H.RelationCounts = ( select O.[Predicate], O.PredicateId, O.PredicateUid, O.Direction, count(1) as [Count] from @relItems O where O.Hop = H.Hop and O.AssetID = H.AssetID group by O.[Predicate], O.PredicateId, O.PredicateUid, O.Direction for json path ) from #hierarchies H;
-- Now return the data sets to caller. select distinct Hop, ID, [Key], ParentKey, Back, Fore, Icon, HierarchyLevel, AssetTypeID, AssetID, AssetUid, DisplayValue, Class, AssetTypeName, Reveal, RelationCounts from #hierarchies order by Hop, ID, HierarchyLevel;
select [Hop], Uid, subjectUid, coalesce( FromKey, utility.GetHash(cast([FromHop] as varchar) + '|' + cast(FromID as varchar(50))) ) as [subjectKey], FromID as subjectId, objectUid, coalesce( ToKey, utility.GetHash(cast([ToHop] as varchar) + '|' + cast(ToID as varchar(50))) ) as [objectKey], ToID as objectId, predicateId, predicateUid, [predicate], predicateType from #tbl order by Hop; end
